import datetime
import hashlib
import json
import os
from pathlib import Path
import re
import stat
import subprocess
import time

command = "find . -type f -print0 | sort -z | xargs -0 sha256sum | sha256sum"
targets = [("R0", 4012737), ("R2", 4013072)]

def now():
    return datetime.datetime.now(datetime.timezone.utc).isoformat()

def process(pid):
    path = Path('/proc') / str(pid)
    try:
        fields = (path / 'stat').read_text().rsplit(')', 1)[1].split()
        return {'pid': pid, 'present': True, 'state': fields[0], 'start_ticks': int(fields[19]), 'argv': [part.decode('utf-8', 'replace') for part in (path / 'cmdline').read_bytes().split(b'\0') if part]}
    except FileNotFoundError:
        return {'pid': pid, 'present': False}

def inventory(root):
    records = []
    regular_count = 0
    regular_bytes = 0
    unsupported = []
    unsafe_names = []
    def failed(error):
        raise error
    for base, directories, files in os.walk(root, topdown=True, followlinks=False, onerror=failed):
        for name in directories + files:
            path = Path(base) / name
            relative = str(path.relative_to(root))
            info = path.lstat()
            if not all(32 <= ord(character) <= 126 for character in relative) or '\\' in relative:
                unsafe_names.append(relative)
            records.append([relative, info.st_dev, info.st_ino, info.st_mode, info.st_size, info.st_mtime_ns, info.st_ctime_ns])
            if stat.S_ISREG(info.st_mode):
                regular_count += 1
                regular_bytes += info.st_size
            elif not stat.S_ISDIR(info.st_mode):
                unsupported.append(relative)
    records.sort(key=lambda entry: entry[0].encode('utf-8'))
    fingerprint = hashlib.sha256(json.dumps(records, sort_keys=True, separators=(',', ':'), ensure_ascii=True).encode()).hexdigest()
    return {'stat_inventory_sha256': fingerprint, 'entries_including_directories': len(records), 'regular_files': regular_count, 'regular_bytes': regular_bytes, 'nonregular_nondirectory_paths': unsupported, 'unsafe_checksum_pathnames': unsafe_names}

def markers(root):
    result = {}
    for name in ('FAILED.json', 'SEAL.json', 'FINALIZED.json', 'RESOURCE.json', 'FINALIZATION_ABORT.json'):
        path = root / name
        try:
            details = path.lstat()
            entry = {'present': True, 'regular': stat.S_ISREG(details.st_mode), 'bytes': details.st_size}
            if entry['regular']:
                digest = hashlib.sha256()
                with path.open('rb') as stream:
                    for chunk in iter(lambda: stream.read(1024 * 1024), b''):
                        digest.update(chunk)
                entry['sha256'] = digest.hexdigest()
            result[name] = entry
        except FileNotFoundError:
            result[name] = {'present': False}
    return result

result = {'remote_started_utc': now(), 'hash_pipeline': command, 'pipeline_shell': ['bash', '-o', 'pipefail', '-c'], 'locale_environment': {key: os.environ.get(key) for key in ('LANG', 'LC_ALL', 'LC_COLLATE', 'LC_CTYPE')}, 'roots': []}
for replica, pid in targets:
    root = Path('/localhome/local-rohing/astra_diagnostics') / ('q0_fulldose_' + replica + '_20260913_attempt1')
    beginning = time.perf_counter()
    observed = {'replica': replica, 'root': str(root), 'started_utc': now(), 'status': 'NOT_VERIFIED', 'custody_only': True}
    try:
        observed['controller_before'] = process(pid)
        if observed['controller_before']['present']:
            raise ValueError('Expected terminal controller PID is still present; no hash pipeline run')
        if not root.is_dir() or root.is_symlink():
            raise ValueError('Expected nonsymlink root directory missing')
        observed['markers_before'] = markers(root)
        if not observed['markers_before']['FINALIZED.json'].get('regular'):
            raise ValueError('Regular FINALIZED.json is required before hashing')
        observed['controller_absence_and_finalized_checked_utc'] = now()
        observed['inventory_before'] = inventory(root)
        if observed['inventory_before']['unsafe_checksum_pathnames'] or observed['inventory_before']['nonregular_nondirectory_paths']:
            raise ValueError('Unsupported file type or checksum pathname; no hash pipeline run')
        observed['hash_started_utc'] = now()
        timer = time.perf_counter()
        response = subprocess.run(['bash', '-o', 'pipefail', '-c', command], cwd=root, capture_output=True, text=True, check=False)
        observed['hash_duration_seconds'] = round(time.perf_counter() - timer, 6)
        observed['hash_finished_utc'] = now()
        observed['pipeline_exit_code'] = response.returncode
        observed['pipeline_stdout'] = response.stdout
        observed['pipeline_stderr'] = response.stderr
        match = re.fullmatch(r'([0-9a-f]{64})  -\n', response.stdout)
        if response.returncode != 0 or match is None or response.stderr:
            raise ValueError('Checksum pipeline failed or returned unexpected output')
        observed['complete_root_stream_sha256'] = match.group(1)
        observed['inventory_after'] = inventory(root)
        observed['markers_after'] = markers(root)
        observed['controller_after'] = process(pid)
        observed['stat_inventory_unchanged'] = observed['inventory_before'] == observed['inventory_after']
        observed['terminal_marker_bytes_unchanged'] = observed['markers_before'] == observed['markers_after']
        if not observed['stat_inventory_unchanged'] or not observed['terminal_marker_bytes_unchanged'] or observed['controller_after']['present']:
            raise ValueError('Post-terminal root/controller state changed during custody hash')
        observed['regular_files'] = observed['inventory_after']['regular_files']
        observed['status'] = 'POST_TERMINAL_FULL_ROOT_CUSTODY_RECORDED'
    except (OSError, ValueError) as error:
        observed['error'] = {'type': type(error).__name__, 'message': str(error)}
    observed['finished_utc'] = now()
    observed['duration_seconds'] = round(time.perf_counter() - beginning, 6)
    result['roots'].append(observed)
result['remote_finished_utc'] = now()
print(json.dumps(result, sort_keys=True, allow_nan=False))
